<script setup>import{onMounted,ref}from'vue';import{teacherApi,formatTime,statusNames}from'../../api/teacher';const rows=ref([]),error=ref('');onMounted(async()=>{try{rows.value=(await teacherApi.gradingExams()).data}catch(e){error.value=e.message}})</script><template><header class="page-heading"><div><p class="eyebrow">GRADING</p><h1>考试阅卷</h1><p class="muted">选择考试查看已提交答卷。</p></div></header><p v-if="error" class="error-message">{{error}}</p><p v-if="!rows.length" class="empty-state">暂无可阅卷考试。</p><div v-else class="table-scroll"><table><thead><tr><th>考试</th><th>状态</th><th>结束时间</th><th>答卷</th><th></th></tr></thead><tbody><tr v-for="e in rows" :key="e.id"><td><strong>{{e.title}}</strong><small>{{e.courseName}}</small></td><td><span :class="['badge',e.status]">{{statusNames[e.status]}}</span></td><td>{{formatTime(e.endTime)}}</td><td>{{e.submissionCount}} 份 / 待处理 {{e.pendingCount}}</td><td><RouterLink :to="'/teacher/grading/exams/'+e.id">查看答卷 →</RouterLink></td></tr></tbody></table></div></template>
